-- ============================================================
-- AG STORE — ĐỒNG BỘ TỔNG THỂ 130 SẢN PHẨM TỪ KHO A_long
-- Nguồn: Hàng nhập (58 ảnh) + Hàng tổng hợp (72 ảnh)
-- Ảnh đồng bộ lên Storage Bucket: https://amycyqggsvucaeqamxpx.supabase.co/storage/v1/object/public/zaloshop-images/
-- An toàn chạy lại nhiều lần (tự tạo bảng/cột/bucket & ON CONFLICT DO UPDATE)
-- ============================================================

create table if not exists public.zaloshop_products (
  id text primary key,
  warehouse_name text not null default 'A_long',
  item_id integer not null default 0,
  code text not null default '',
  category text not null default 'Hàng nhập',
  name text not null,
  so_luong integer not null default 0,
  is_out_of_stock boolean not null default false,
  is_visible boolean not null default true,
  is_featured boolean not null default false,
  ghi_chu text not null default '',
  rel_path text not null default '',
  image_url text not null default '',
  updated_at timestamptz not null default now()
);

alter table public.zaloshop_products add column if not exists is_visible boolean not null default true;
alter table public.zaloshop_products add column if not exists is_featured boolean not null default false;

values ('zaloshop-images', 'zaloshop-images', true, 5242880, array['image/jpeg', 'image/png', 'image/webp', 'image/gif'])
on conflict (id) do update set public = true, file_size_limit = 5242880;

on conflict (id) do update set
  warehouse_name = excluded.warehouse_name,
  item_id = excluded.item_id,
  code = excluded.code,
  category = excluded.category,
  name = excluded.name,
  so_luong = excluded.so_luong,
  is_out_of_stock = excluded.is_out_of_stock,
  ghi_chu = excluded.ghi_chu,
  rel_path = excluded.rel_path,
  image_url = excluded.image_url,
  updated_at = now();
